CREATE TABLE IF NOT EXISTS units (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NOT NULL, actual_name VARCHAR(255) NOT NULL, short_name VARCHAR(255) NOT NULL, allow_decimal BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
